using UnityEngine;

namespace BeatFactory
{
    /// <summary>
    /// Layout of the crowd texture atlas (generated by ArtGenerator.CrowdAtlasArt): white/grey parts that are tinted per
    /// fan with vertex colors, so a handful of shapes become thousands of different people (skin, hair, clothes).
    /// Grid of 64×64 cells, 16 × 8. Fans are seen from behind (they face the stage).
    /// </summary>
    public static class CrowdAtlas
    {
        public const int Width = 1024, Height = 512, Cell = 64, Cols = 16, Rows = 8;

        // row 0: torsos seen from behind (hoodie, tee, jacket, tank top, puffer, long dress/coat)
        public const int BodyRow = 0, BodyCount = 6;
        // row 1: hair (back view) 0..9, then bare head (back), head turned (side face)
        public const int HairRow = 1, HairCount = 10, HeadBackCol = 10, HeadSideCol = 11, CapCol = 12, BeanieCol = 13;
        // row 2: props
        public const int PropRow = 2;
        public const int ArmCol = 0, SleeveCol = 1, PhoneCol = 2, GlowCol = 3, SignCol = 4, FarCol = 5, FarHandsCol = 6, FarWideCol = 7, FlashCol = 8, BarrierCol = 9;

        public static Rect UV(int col, int row) =>
            new Rect(col * Cell / (float)Width, row * Cell / (float)Height, Cell / (float)Width, Cell / (float)Height);

        // ---- geometry inside a cell (pixels, origin bottom-left) — shared by the painter and the renderer
        /// <summary>Neck point of a torso cell.</summary>
        public static readonly Vector2 Neck = new Vector2(32, 54);
        /// <summary>Shoulders of a torso cell (left / right as seen from behind).</summary>
        public const float ShoulderX = 19, ShoulderY = 47;
        /// <summary>Head center in a hair / head cell and its radius.</summary>
        public static readonly Vector2 HeadCenter = new Vector2(32, 30);
        public const float HeadRadius = 15;
        /// <summary>Arm cell: shoulder at the top, hand at the bottom.</summary>
        public const float ArmTop = 62, ArmBottom = 6, ArmWidth = 12;
    }
}
